def field(kind='route'):
    marks={'route':'<path d="M185 175 Q240 130 310 156 T452 222" fill="none" stroke="#a5b4fc" stroke-width="5" stroke-dasharray="10 6"/><circle cx="185" cy="175" r="8" fill="#38bdf8"/><circle cx="452" cy="222" r="8" fill="#38bdf8"/>','save':'<path d="M360 160 L200 260" stroke="#fb923c" stroke-width="4"/><circle cx="200" cy="260" r="8" fill="#f8fafc"/><circle cx="222" cy="292" r="8" fill="#38bdf8"/>','shot':'<path d="M310 220 L380 70" stroke="#38bdf8" stroke-width="4"/><circle cx="310" cy="220" r="8" fill="#38bdf8"/><circle cx="380" cy="70" r="7" fill="#f8fafc"/>'}[kind]
    return '<svg class="field" viewBox="0 0 640 360" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Illustrative Rocket League pitch with a highlighted review route"><defs><linearGradient id="g" x2="0" y2="1"><stop stop-color="#172840"/><stop offset="1" stop-color="#142133"/></linearGradient></defs><rect x="105" y="24" width="430" height="312" rx="58" fill="url(#g)" stroke="#34455e" stroke-width="2"/><path d="M105 180H535" stroke="#52627d" stroke-width="1.5"/><circle cx="320" cy="180" r="52" fill="none" stroke="#52627d" stroke-width="1.5"/><rect x="246" y="11" width="148" height="27" rx="6" fill="#fb923c22" stroke="#fb923c"/><rect x="246" y="322" width="148" height="27" rx="6" fill="#38bdf822" stroke="#38bdf8"/><path d="M208 38V80H432V38M208 322V280H432V322" fill="none" stroke="#34455e"/><g fill="#f59e0b" opacity=".8">'+''.join(f'<circle cx="{x}" cy="{y}" r="3"/>' for x,y in [(180,90),(460,90),(180,270),(460,270),(245,142),(395,142),(245,218),(395,218),(320,110),(320,250)])+'</g>'+marks+'<circle cx="415" cy="146" r="8" fill="#fb923c"/><circle cx="358" cy="106" r="8" fill="#fb923c"/><circle cx="298" cy="266" r="8" fill="#38bdf8"/></svg>'

def linechart(compact=False):
    return '<svg class="'+('trend' if compact else 'chart')+'" viewBox="0 0 640 210" preserveAspectRatio="none" role="img" aria-label="Illustrative low-boost exposure across 25 games, with rolling mean and baseline"><g stroke="#ffffff10">'+''.join(f'<path d="M35 {y}H625"/>' for y in [25,70,115,160])+'</g><path d="M35 87 H625" fill="none" stroke="#94a3b8" stroke-width="1.5" stroke-dasharray="5 5"/><path d="M35 65 L60 49 L85 81 L110 52 L135 92 L160 76 L185 55 L210 102 L235 85 L260 67 L285 110 L310 102 L335 88 L360 127 L385 107 L410 139 L435 117 L460 153 L485 134 L510 165 L535 145 L560 171 L585 158 L625 160" fill="none" stroke="#6366f1" stroke-opacity=".35" stroke-width="2"/><path d="M35 65 C130 66 175 73 225 80 S340 103 395 116 S510 148 625 160" fill="none" stroke="#a5b4fc" stroke-width="3"/><circle cx="625" cy="160" r="5" fill="#a5b4fc"/><g fill="#94a3b8" font-family="Inter,sans-serif" font-size="11"><text x="2" y="30">35%</text><text x="2" y="117">25%</text><text x="2" y="164">20%</text><text x="35" y="201">25 games ago</text><text x="555" y="201">Latest game</text></g><path d="M285 15V180" stroke="#34d399" stroke-opacity=".6" stroke-dasharray="3 4"/><text x="293" y="23" fill="#34d399" font-size="11">Practice started</text></svg>'

navitems=[('today','Today','◈'),('match-report','Matches','▤'),('coach','Coach','◇'),('progress','Progress','↗')]
def shell(key,title,body,canvas=True):
    nav=''.join(f'<a href="{name}.html" class="'+('active' if key==name else '')+f'" '+('aria-current="page"' if key==name else '')+f'><span class="ico">{icon}</span><span class="navlabel">{label}</span>'+('<small>86</small>' if name=='match-report' else '')+'</a>' for name,label,icon in navitems)
    side=f'<aside class="side"><a class="brand" href="today.html"><span class="brandmark">⬡</span><span>AntiRL</span></a><nav class="nav" aria-label="Primary">{nav}<a href="replay-studio.html"><span class="ico">▷</span><span class="navlabel">Replay Studio</span></a></nav><div class="sidefoot"><div class="row"><span class="avatar">N</span><div class="profiletext"><strong>Nova</strong><div class="label">Diamond II · 2v2</div></div></div><p class="sub" style="margin-top:17px"><span class="green">●</span> Watching replay folder</p><a class="sub" style="display:block;margin-top:14px" href="onboarding.html">Settings & profile</a></div></aside>'
    top=f'<header class="top"><div class="breadcrumb">{title}</div><div class="row"><span class="kbd">Find a match, moment or action <kbd>Ctrl K</kbd></span><button class="quiet" data-action="The import queue opens here. Mockup only.">＋ Import</button></div></header>'
    return f'<a class="skip" href="#main">Skip to content</a><div class="shell">{side}<div class="content">{top}<main id="main" class="'+('canvas'+(' reportview' if key=='match-report' else '') if canvas else '')+'">'+body+'</main></div></div>'

def pagehead(title,subtitle,actions=''):
    return f'<div class="pagehead"><div><h1>{title}</h1><p class="sub">{subtitle}</p></div><div class="row">{actions}</div></div>'
def statstrip(items):
    return '<div class="statstrip">'+''.join(f'<div class="stat"><div class="label">{label}</div><div class="large num">{val}</div><small>{note}</small></div>' for label,val,note in items)+'</div>'
def moment(num,time,title,description,kind='route',badge='Estimated'):
    seconds=int(time.split(':')[0])*60+int(time.split(':')[1])
    return f'<article class="panel moment"><div class="thumb">{field(kind)}</div><div class="row between"><span class="eyebrow">Moment {num}</span><span class="time">{time}</span></div><h3 style="margin-top:8px">{title}</h3><p>{description}</p><footer><span class="badge '+('measured' if badge=='Measured' else 'estimated')+f'">{badge}</span><a class="time" href="replay-studio.html?t={seconds}">Watch moment ↗</a></footer></article>'

